  counter := counter^ + 1;
};

functions.code:
let add = (x, y) => x + y;

/* Recursive function */
let rec factorial = (n) =>
  if (n == 0) { 1 } else { n * factorial(n - 1) };

/* Labeled arguments */
let greet = (~greeting, ~name) => greeting ++ ", " ++ name;
greet(~name="Bob", ~greeting="Hello");

