error_handling.code:
exception DivByZero;

let div = (x, y) => 
  if (y == 0) { raise(DivByZero) } else { x / y };

let safe = 
  try (div(10, 0)) {
  | DivByZero => 0
  };

/* Option type */
let safeDiv = (x, y) =>
  if (y == 0) { None } else { Some(x / y) };
